"""results/temporal/weights_scale/REPORT.md from the JSONs. Run: python scripts/make_ws.py"""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from boa_dit.common import atomic_write_text
from boa_dit.weights_joint.common import boot_reduction
from boa_dit.weights_scale.run import OUT, spent
J = lambda f: json.load(open(os.path.join(OUT, f)))
p = lambda r: f"{-100 * r['reduction']:+.1f}% [{-100 * r['ci'][1]:+.1f}, {-100 * r['ci'][0]:+.1f}]"
v, rf, fit, fr, ev = J("validation.json"), J("refit.json"), J("fit.json"), J("frozen.json"), J("eval.json")
A = ev["arms"]
L = ["# Fixed-code scale modulation of heig-8 W4: report (generated by `scripts/make_ws.py`; protocol `PROTOCOL.md`)", "",
     f"Compute: {spent():.3f} of 1.0 A30-h (stage `weights_scale`). One packed W4 table; only per-layer output multipliers vary; the rank-8 carry is not scaled; activations high precision.", "",
     f"**Validation:** c ≡ 1 bit-exact vs heig-8: {v['c1_bitexact_vs_heig8']}; output scaling = weight scaling to {v['output_vs_weight_scaling_max_rel']:.1e}; symmetric-average identity to {v['symmetric_average_max_rel']:.1e}.", "",
     f"**Static refit:** c* family means {', '.join(f'{k} {x:.4f}' for k, x in rf['by_family_mean'].items())}; boundary hits {len(rf['boundary_hits'])}. heig-8's scales are already locally optimal.", "",
     "**Endpoint fit (seeds 5000–5007; λ on 5008–5023):** the finite-difference resolution check **fails**. In the alternating pattern R(2ε) and R(ε) "
     "differ by " + ", ".join(f"{k.split('_')[0]} {x:.0%}" for k, x in fit["patterns"]["alternating"]["fd_checks"].items() if "R2eps" in k)
     + ". At ε = 0.005 the fp16 endpoint response is far from linear, so the fitted amplitudes are not a resolved optimum. The evaluation below tests these frozen coefficients by actual sampling.", "",
     "| pattern | amplitudes a (qkv, proj, fc1, fc2) | chosen λ (× mean diag) | validation latent |", "| --- | --- | ---: | ---: |"]
for pn, x in fit["patterns"].items():
    a = x["a"]
    L.append(f"| {pn} | {a['attn.qkv']:+.4f}, {a['attn.proj']:+.4f}, {a['mlp.fc1']:+.4f}, {a['mlp.fc2']:+.4f} | {x['chosen_lambda_rel']:g} | {x['lambda_grid'][str(x['chosen_lambda_rel'])]['val_rel_mse']:.5f} |")
L += [f"| (static refit) | — | — | {fit['val_static_refit_rel_mse']:.5f} |", "",
      "## Evaluation (reserved seeds 4100–4227, 128, used once after the freeze)", "",
      "| arm | latent rel. MSE | vs static refit [95% CI] | vs endpoint-fitted constant | prediction C (abs.) | C/I | sampling s (sim.) |", "| --- | ---: | --- | --- | ---: | ---: | ---: |"]
for k, x in A.items():
    L.append(f"| {k} | {x['rel_mse_mean']:.5f} | {p(x['vs_static_refit']) if 'vs_static_refit' in x else '—'} | {p(x['vs_constant']) if 'vs_constant' in x else '—'} | "
             f"{x['diag']['C']:.4g} | {x['diag']['C_over_I']:.4f} | {x['sampling_s']:.0f} |")
ras = boot_reduction(A["alternating"]["rel_mse_per_seed"], A["shuffled"]["rel_mse_per_seed"])
L += ["", f"Alternating vs shuffled (ordering ablation): {p(ras)}. Static refit vs original: {p(A['static_refit']['vs_original'])}.", "",
      "## Reading", "",
      "- **No temporal benefit is established.** The endpoint-fitted *constant* (static) arm is the best point estimate but is not significantly better than the static refit; slow beats the refit slightly but not the constant; alternating equals the refit, and its ordering ablation (shuffled) shows no reliable difference.",
      "- **Alternation lowers coherence without moving the endpoint** (C/I 0.267 → 0.231, the same in the shuffled order): the symmetric modulation re-shapes the error over time, but its fixed-input average is the baseline's, and here that re-shaping does not translate into endpoint gain.",
      "- **Static refit:** c* differs from 1 by ≈ 3×10⁻⁴, yet the refit improves the endpoint by 1.6% (CI excluding 0): a small but real static correction.",
      "- **Caveat:** the amplitude fit did not pass its resolution check, so these results test particular small-amplitude coefficients, not the best achievable scale schedule. A resolved test needs fp32 (or larger-ε) finite differences.",
      "- **Cost:** storage 112 fp16 multipliers (folded into scales) + 4 amplitudes + the pattern rule. The simulation's sampling time rises from 77 s to 136 s because the c ≠ 1 hook runs in fp32 eager mode; a deployed kernel would fold c into its existing scale (not measured)."]
atomic_write_text(os.path.join(OUT, "REPORT.md"), "\n".join(L) + "\n")
print("\n".join(L))
